import pytest

from digitalremotelab.portcheck import MAX_VHDL_BYTES, VhdlError, check_vhdl

GOOD = """
-- generated by Digital
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity DIG_CounterPreset is
  port (clk : in std_logic; q : out std_logic);
end DIG_CounterPreset;

architecture Behavioral of DIG_CounterPreset is begin q <= clk; end Behavioral;

library ieee;
use ieee.std_logic_1164.all;
use ieee.std_logic_unsigned.all;

entity main is
  port (
    SW0: in std_logic;
    SW1, SW2: in std_logic;
    CLK: in std_logic;
    LED0: out std_logic;
    LED1: out std_logic;
    LED2: out std_logic;
    LED3: out std_logic );
end main;

architecture Behavioral of main is
begin
  LED0 <= SW0;
end Behavioral;
"""


def problems(src):
    with pytest.raises(VhdlError) as exc:
        check_vhdl(src)
    return "\n".join(exc.value.problems)


def test_digital_example_is_accepted():
    info = check_vhdl(GOOD)
    assert info.inputs == ("SW0", "SW1", "SW2", "CLK")
    assert info.outputs == ("LED0", "LED1", "LED2", "LED3")


def test_bytes_and_case_insensitive_names():
    info = check_vhdl(GOOD.replace("LED0", "led0").encode())
    assert "LED0" in info.outputs


def test_display_ports_are_accepted():
    src = GOOD.replace(
        "LED3: out std_logic", "SEG_A: out std_logic; SEG_DP: out std_logic; AN7: out std_logic"
    )
    assert {"SEG_A", "SEG_DP", "AN7"} <= set(check_vhdl(src).outputs)


def test_missing_main():
    assert "«main»" in problems(
        GOOD.replace("entity main", "entity otra").replace("end main", "end otra")
    )


def test_unknown_port_name_lists_valid_ones():
    msg = problems(GOOD.replace("LED3", "LEDX"))
    assert "LEDX" in msg and "LED0" in msg


def test_input_cannot_be_used_as_output():
    assert "salida válida" in problems(GOOD.replace("LED3: out", "SW9: out"))


def test_vectors_are_rejected():
    assert "std_logic de 1 bit" in problems(
        GOOD.replace("SW0: in std_logic", "SW0: in std_logic_vector(3 downto 0)")
    )


def test_inout_is_rejected():
    assert "inout" in problems(GOOD.replace("SW0: in", "SW0: inout"))


def test_duplicate_port():
    assert "repetido" in problems(GOOD.replace("SW1, SW2", "SW0, SW2"))


@pytest.mark.parametrize(
    "extra",
    [
        "library unisim;",
        "use ieee.math_real.all;",
        "use std.textio.all;",
        "library xil_defaultlib;",
    ],
)
def test_forbidden_libraries(extra):
    assert (
        "no permitid" in problems(GOOD.replace("entity main", extra + "\nentity main", 1)).lower()
    )


def test_xilinx_primitives_are_rejected_even_without_library_clause():
    src = GOOD.replace(
        "begin\n  LED0",
        "signal c : std_logic;\nbegin\n  b: BUFG port map (I => SW0, O => c);\n  LED0",
    )
    assert "BUFG" in problems(src).upper()


def test_vivado_attributes_are_rejected():
    src = GOOD.replace("begin\n  LED0", "attribute LOC : string;\nbegin\n  LED0")
    assert "atributos" in problems(src)


def test_comments_are_ignored():
    src = GOOD.replace(
        "architecture Behavioral of main",
        "-- library unisim; BUFG\narchitecture Behavioral of main",
    )
    check_vhdl(src)


def test_all_problems_are_reported_together():
    msg = problems(
        GOOD.replace("LED3", "LEDX")
        .replace("SW1,", "SWQ,")
        .replace("library ieee;", "library unisim;")
    )
    assert "LEDX" in msg and "SWQ" in msg and "unisim" in msg


def test_no_outputs():
    src = """entity main is port (SW0: in std_logic); end main;"""
    assert "ninguna salida" in problems(src)


def test_size_limit_and_encoding():
    assert "grande" in problems(b" " * (MAX_VHDL_BYTES + 1))
    assert "UTF-8" in problems(b"\xff\xfe\x00")


def test_garbage_does_not_crash():
    for src in ["", "entity main is end main;", "entity main is port (x); end main;"]:
        problems(src)
